/*
 * showkey.c -- display cooked key sequences
 *
 * Invoke this (no arguments needed) to see keycap-to-keystrokes mappings.
 *
 * SPDX-FileCopyrightText: (C) Eric S. Raymond <esr@thyrsus.com>
 * SPDX-License-Identifier: MIT
 */
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <termios.h>
#include <unistd.h>

#define ALT 0x80

static char *lowchars[] = {
    "NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL", "BS",  "HT",  "LF",
    "VT",  "FF",  "CR",  "SO",  "SI",  "DLE", "DC1", "DC2", "DC3", "DC4", "NAK",
    "SYN", "ETB", "CAN", "EM",  "SUB", "ESC", "FS",  "GS",  "RS",  "US",  "SP",
};

static struct termios cooked, raw;

static volatile sig_atomic_t got_signal = 0;

static void restore_tty(void) {
	(void)tcsetattr(0, TCSANOW, &cooked);
}

static void catcher(const int sig) {
	got_signal = sig;
}

#define STARTCOOKIE '<'
#define ENDCOOKIE '>'

static void visualize(int c, char *buf) {
	char *end;
	bool cookie = false;

	buf[0] = '\0';
	if ((c & ALT) != 0) {
		cookie = true;
		c &= ~ALT;
		buf[0] = STARTCOOKIE;
		buf[1] = '\0';
		(void)strcat(buf, "ALT-");
	}

	if (c <= ' ') {
		cookie = true;
		end = buf + strlen(buf);
		if (buf[0] != STARTCOOKIE) {
			*end++ = STARTCOOKIE;
			*end++ = '\0';
		}
		if (c > 0 && c < 27) {
			(void)strcat(buf, "CTL-");
			end = buf + strlen(buf);
			*end++ = (c + 0x40);
			*end++ = '=';
			*end = 0;
		}
		(void)strcat(buf, lowchars[c]);
	} else if (c == 0x7f) {
		cookie = true;
		if (buf[0] != STARTCOOKIE) {
			buf[0] = STARTCOOKIE;
			buf[1] = '\0';
		}
		(void)strcat(buf, "DEL");
	} else {
		end = buf + strlen(buf);
		*end++ = c;
		*end = '\0';
	}

	if (cookie) {
		end = buf + strlen(buf);
		*end++ = ENDCOOKIE;
		*end++ = '\0';
	}
}

int main() {
	unsigned char c;
	char intrchar[32], quitchar[32];

	{
		struct sigaction sa;
		sigemptyset(&sa.sa_mask);
		sa.sa_handler = catcher;
		sa.sa_flags = 0;
		(void)sigaction(SIGHUP, &sa, NULL);
		(void)sigaction(SIGINT, &sa, NULL);
		(void)sigaction(SIGQUIT, &sa, NULL);
		(void)sigaction(SIGTERM, &sa, NULL);
	}

	if (!isatty(0)) {
		(void)fprintf(stderr, "stdin is not a tty\n");
		return 1;
	}
	// Get the state of the tty
	if (tcgetattr(0, &cooked) != 0) {
		(void)perror("tcgetattr");
		return 1;
	}
	(void)atexit(restore_tty);
	// Make a copy we can mess with
	(void)memcpy(&raw, &cooked, sizeof(struct termios));
	// Turn off echoing, linebuffering, and special-character processing,
	// but not the SIGINT or SIGQUIT keys.
	raw.c_lflag &= ~(ICANON | ECHO);
	// Ship the raw control blts
	if (tcsetattr(0, TCSANOW, &raw) != 0) {
		(void)perror("tcsetattr");
		return 1;
	}

	(void)printf("Type any key to see the sequence it sends.\n");
	visualize(raw.c_cc[VINTR], intrchar);
	visualize(raw.c_cc[VQUIT], quitchar);
	(void)printf(
	    "Terminate with your shell interrupt %s or quit %s character.\n",
	    intrchar, quitchar);
	for (;;) {
		char cbuf[32];

		if (got_signal != 0) {
			break;
		}
		{
			ssize_t nread;
			do {
				nread = read(0, &c, 1);
			} while (nread < 0 && errno == EINTR && got_signal == 0);
			if (nread < 0) {
				(void)perror("read");
				break;
			}
			if (nread == 0) {
				break;
			}
		}
		visualize(c, cbuf);
		(void)fputs(cbuf, stdout);
		(void)fflush(stdout);
	}

	(void)printf("\nBye...\n");
}

/* showkey.c ends here */
"}]}

